func:
// Lấy số lần tưới hiện tại.
// Nếu chưa có thì mặc định là 0.
let count = flow.get("wateringCount") || 0;

// Mỗi lần bấm inject giả lập, tăng số lần tưới lên 1.
count = count + 1;

// Lưu lại vào bộ nhớ flow của Node-RED.
flow.set("wateringCount", count);

// In nội dung ra debug để kiểm tra.
msg.payload = "Số lần tưới hôm nay: " + count;

return msg;

// Lấy số lần tưới đã lưu
let count = flow.get("wateringCount") || 0;

// Lấy thời gian hiện tại
let now = new Date();

let timeText = now.toLocaleString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh"
});

// Email người nhận.
// Có thể đổi thành email của bạn.
msg.to = "bthloan2006@gmail.com";

// Tiêu đề email
msg.topic = "Báo cáo tưới nước hằng ngày - Vườn thông minh IoT";

// Nội dung email
msg.payload =
    `BÁO CÁO HỆ THỐNG VƯỜN THÔNG MINH IOT

Thời gian gửi báo cáo: ${timeText}

Hôm nay hệ thống đã kích hoạt tưới nước: ${count} lần.

Ghi chú:
- Đây là email báo cáo định kỳ hằng ngày.
- Chức năng này dùng riêng cho yêu cầu Email.
- Không dùng chung điều kiện với thông báo nhanh.

Trân trọng,
Hệ thống Vườn Thông Minh IoT`;

return msg;

// Sau khi gửi email báo cáo xong,
// reset số lần tưới về 0 để bắt đầu chu kỳ mới.
flow.set("wateringCount", 0);

msg.payload = "Đã gửi email và reset số lần tưới về 0.";

return msg;

const status = String(msg.payload || "")
    .trim()
    .toUpperCase();

if (status !== "ONLINE" && status !== "OFFLINE") {
    return null;
}

msg.payload = status;
return msg;

const form = msg.payload || {};

const username = String(form.username || "")
    .trim()
    .toLowerCase();

const email = String(form.email || "")
    .trim()
    .toLowerCase();

const password = String(form.password || "");
const confirmPassword = String(form.confirm_password || "");

function reject(message) {
    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true,
        allowDismiss: true,
        dismissText: "Đóng"
    };

    return [null, msg];
}

if (!username) {
    return reject("Vui lòng nhập tên đăng nhập.");
}

if (!email) {
    return reject("Vui lòng nhập email.");
}

if (!password) {
    return reject("Vui lòng nhập mật khẩu.");
}

if (!confirmPassword) {
    return reject("Vui lòng xác nhận mật khẩu.");
}

if (username.length < 4) {
    return reject("Tên đăng nhập phải có ít nhất 4 ký tự.");
}

if (!/^[a-z0-9_]+$/.test(username)) {
    return reject(
        "Tên đăng nhập chỉ được chứa chữ không dấu, số và dấu gạch dưới."
    );
}

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return reject("Email không đúng định dạng.");
}

if (password.length < 8) {
    return reject("Mật khẩu phải có ít nhất 8 ký tự.");
}

if (password !== confirmPassword) {
    return reject("Mật khẩu xác nhận không khớp.");
}

msg.registerForm = {
    username,
    email,
    password
};

msg.payload = null;

return [msg, null];

const form = msg.registerForm;
const rows = Array.isArray(msg.payload)
    ? msg.payload
    : [];

// Bỏ hàng tiêu đề
const users = rows.slice(1);

function reject(message) {
    delete msg.registerForm;

    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true,
        allowDismiss: true,
        dismissText: "Đóng"
    };

    return [null, msg];
}

if (!form) {
    return reject("Không tìm thấy dữ liệu đăng ký.");
}

const usernameExists = users.some(row =>
    String(row[1] || "").trim().toLowerCase() === form.username
);

if (usernameExists) {
    return reject("Tên đăng nhập đã tồn tại.");
}

const emailExists = users.some(row =>
    String(row[2] || "").trim().toLowerCase() === form.email
);

if (emailExists) {
    return reject("Email đã được đăng ký.");
}

const passwordHash = bcryptjs.hashSync(form.password, 10);

const userId = "USR-" + Date.now();

msg.payload = [
    userId,
    form.username,
    form.email,
    passwordHash,
    new Date().toISOString(),
    "active",
    ""
];

// Xóa mật khẩu gốc khỏi message
delete msg.registerForm;

return [msg, null];

msg.payload = "Đăng ký tài khoản thành công!";

msg.ui_update = {
    color: "#2e7d32",
    displayTime: 5,
    position: "top center",
    showCountdown: true,
    allowDismiss: true,
    dismissText: "Đóng"
};

return msg;

const form = msg.payload || {};

const username = String(form.username || "")
    .trim()
    .toLowerCase();

const password = String(form.password || "");

function reject(message) {
    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    };

    return [null, msg];
}

if (!username) {
    return reject("Vui lòng nhập tên đăng nhập.");
}

if (!password) {
    return reject("Vui lòng nhập mật khẩu.");
}

// Giữ thông tin để kiểm tra sau khi đọc Google Sheets
msg.loginForm = {
    username,
    password
};

msg.payload = null;

return [msg, null];

const form = msg.loginForm;

const rows = Array.isArray(msg.payload)
    ? msg.payload
    : [];

function reject(message) {
    delete msg.loginForm;

    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    };

    return [null, msg];
}

if (!form) {
    return reject("Không tìm thấy dữ liệu đăng nhập.");
}

// Bỏ hàng tiêu đề Google Sheets
const users = rows.slice(1);

// Tìm tài khoản theo username ở cột B, tức row[1]
const account = users.find(row =>
    String(row[1] || "")
        .trim()
        .toLowerCase() === form.username
);

if (!account) {
    return reject(
        "Tên đăng nhập hoặc mật khẩu không đúng."
    );
}

// Cột F là status, tức row[5]
const status = String(account[5] || "")
    .trim()
    .toLowerCase();

if (status !== "active") {
    return reject("Tài khoản hiện không hoạt động.");
}

// Cột D là password_hash, tức row[3]
const passwordHash = String(account[3] || "");

let passwordCorrect = false;

try {
    passwordCorrect = bcryptjs.compareSync(
        form.password,
        passwordHash
    );
} catch (error) {
    passwordCorrect = false;
}

if (!passwordCorrect) {
    return reject(
        "Tên đăng nhập hoặc mật khẩu không đúng."
    );
}

const socketId = msg._client?.socketId;

if (!socketId) {
    return reject(
        "Không xác định được phiên trình duyệt. Hãy tải lại trang."
    );
}

// Lưu phiên riêng theo từng trình duyệt
const sessions = flow.get("auth_sessions") || {};

sessions[socketId] = {
    user_id: String(account[0]),
    username: String(account[1]),
    email: String(account[2]),
    expires_at: Date.now() + 30 * 60 * 1000
};

flow.set("auth_sessions", sessions);

msg.auth = sessions[socketId];

delete msg.loginForm;

msg.payload =
    "Đăng nhập thành công. Chào " +
    msg.auth.username +
    "!";

msg.ui_update = {
    color: "#2e7d32",
    displayTime: 5,
    position: "top center",
    showCountdown: true
};

return [msg, null];

const AUTH_PAGE = "Tài khoản";
const SYSTEM_PAGE = "Hệ thống vườn";

// Output 1: hiện hệ thống và ẩn trang tài khoản
const visibilityMsg = {
    ...msg,
    payload: {
        pages: {
            show: [SYSTEM_PAGE],
            hide: [AUTH_PAGE]
        }
    }
};

// Output 2: chuyển sang trang hệ thống
const navigationMsg = {
    ...msg,
    payload: {
        page: SYSTEM_PAGE
    }
};

// Output 3: thông báo thành công
const notificationMsg = {
    ...msg,
    payload:
        "Đăng nhập thành công. Chào " +
        msg.auth.username +
        "!",
    ui_update: {
        color: "#2e7d32",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    }
};

return [
    visibilityMsg,
    navigationMsg,
    notificationMsg
];

// Chỉ xử lý khi nút gửi giá trị Boolean true
const socketId = msg._client?.socketId;
const sessions = flow.get("auth_sessions") || {};

const session = socketId
    ? sessions[socketId]
    : null;

const sessionValid =
    session &&
    session.user_id &&
    session.email &&
    Number(session.expires_at) > Date.now();

if (!sessionValid) {
    msg.payload =
        "Không thể gửi email. Phiên đăng nhập không hợp lệ.";

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    };

    return [null, msg];
}

// Gán thông tin tài khoản cho Function phía sau
msg.auth = session;

// Node e-mail sẽ lấy người nhận từ msg.to
msg.to = String(session.email).trim();

return [msg, null];

// Lấy số lần tưới đã lưu
let count = flow.get("wateringCount") || 0;

// Lấy thời gian hiện tại
let now = new Date();

let timeText = now.toLocaleString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh"
});

const recipient = String(msg.to || "").trim();

if (!recipient) {
    node.error(
        "Không tìm thấy địa chỉ người nhận trong msg.to",
        msg
    );

    return null;
}

// Email người nhận.
// Có thể đổi thành email của bạn.
msg.to = recipient;

// Tiêu đề email
msg.topic = "Báo cáo tưới nước hằng ngày - Vườn thông minh IoT";

// Nội dung email
msg.payload =
    `BÁO CÁO HỆ THỐNG VƯỜN THÔNG MINH IOT

Thời gian gửi báo cáo: ${timeText}

Hôm nay hệ thống đã kích hoạt tưới nước: ${count} lần.

Ghi chú:
- Đây là email báo cáo định kỳ hằng ngày.
- Chức năng này dùng riêng cho yêu cầu Email.
- Không dùng chung điều kiện với thông báo nhanh.

Trân trọng,
Hệ thống Vườn Thông Minh IoT`;

return msg;

// Sau khi gửi email báo cáo xong,
// reset số lần tưới về 0 để bắt đầu chu kỳ mới.
flow.set("wateringCount", 0);

msg.payload = "Đã gửi email và reset số lần tưới về 0.";

return msg;

let NhietDo = Math.round(Math.random() * 20) + 20
let DoAm = Math.round(Math.random() * 100)
let AnhSang = Math.round(Math.random() * 500) + 100

msg.payload = {
    "nhiet_do": NhietDo,
    "do_am": DoAm,
    "anh_sang": AnhSang
}

return msg;

let data = msg.payload;
if (typeof data === 'string') {
    data = JSON.parse(data);
}

let msg1 = { payload: data.nhiet_do, topic: "Nhiệt độ" };
let msg2 = { payload: data.do_am, topic: "Độ ẩm" };
let msg3 = { payload: data.anh_sang, topic: "Ánh sáng" };

return [msg1, msg2, msg3];

let status = msg.payload.status;

flow.set("den_status", status);

msg.payload = {
    device: "den",
    status: status
};

return msg;

let status = msg.payload.status;

flow.set("quat_status", status);

msg.payload = {
    device: "quat",
    status: status
};

return msg;
